272	
273	    /**
274	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where REGION is
275	     * the region derived from the owner's postcode (preferring the postcode, falling back to the
276	     * city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}) and HASH8 is the
277	     * first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized E.164
278	     * telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no
279	     * sequence number, so its base form is a stable function of the owner's region and
280	     * telephone/last-name identity rather than of creation order.
281	     *
282	     * <p>When that computed code already belongs to an existing owner it is de-duplicated by
283	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a code no
284	     * existing owner already has; the de-duplicated code is returned.
285	     *
286	     * @param owner the owner being created, with its telephone already normalized to E.164 form
287	     * @return the assigned, collision-free customer code
288	     */
289	    private String customerCodeFor(Owner owner) {
290	        String region = ownerMapper.regionOf(owner);
291	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName()).substring(0, 8);
292	        String baseCode = region + "-" + hash8;
293	        if (!isCustomerCodeInUse(baseCode)) {
294	            return baseCode;
295	        }
296	        int n = 2;
297	        String candidate = baseCode + "-" + n;
298	        while (isCustomerCodeInUse(candidate)) {
299	            n++;
300	            candidate = baseCode + "-" + n;
301	        }
302	        return candidate;
303	    }
304	
305	    /**
306	     * Determines whether any existing owner already carries the given {@code customerCode}, compared
307	     * exactly. Called while assigning a new owner's code so collisions can be de-duplicated.
308	     *
309	     * @param customerCode the candidate customer code to look for
310	     * @return {@code true} if an existing owner already has that customer code
311	     */
312	    private boolean isCustomerCodeInUse(String customerCode) {
313	        for (Owner existing : this.clinicService.findAllOwners()) {
314	            if (customerCode.equals(existing.getCustomerCode())) {
315	                return true;
316	            }
317	        }
318	        return false;
319	    }
320	
321	    /**
322	     * Computes the SHA-256 digest of the UTF-8 bytes of {@code value} and renders it as an
323	     * upper-case hex string.
324	     *
325	     * @param value the string to hash
326	     * @return the full SHA-256 digest as upper-case hex
327	     */
328	    private static String sha256UpperHex(String value) {
329	        try {
330	            byte[] digest = MessageDigest.getInstance("SHA-256")
331	                .digest(value.getBytes(StandardCharsets.UTF_8));
332	            StringBuilder sb = new StringBuilder(digest.length * 2);
333	            for (byte b : digest) {
334	                sb.append(String.format("%02X", b));
335	            }
336	            return sb.toString();
337	        } catch (NoSuchAlgorithmException ex) {
338	            throw new IllegalStateException("SHA-256 not available", ex);
339	        }
340	    }
341	
342	    /**
343	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
344	     * owner's city already contains this many owners.
345	     */
346	    private static final int CITY_CAPACITY = 50;
347	
348	    /**
349	     * The maximum number of owners that may be created on a single day. A create is rejected with
350	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
351	     * {@code registrationDate}.
352	     */
353	    private static final int DAILY_CREATE_LIMIT = 100;
354	
355	    /**
356	     * The number of owners that must already have been created for the current day before a new
357	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
358	     * owners already carry today's {@code registrationDate}.
359	     */
360	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
361	
362	    /**
363	     * The fixed public holidays that the business-day roll skips. A registration date landing on one
364	     * of these dates is rolled forward, exactly as it is for a weekend day.
365	     */
366	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
367	        LocalDate.parse("2026-01-01"),
368	        LocalDate.parse("2026-01-26"),
369	        LocalDate.parse("2026-04-25"),
370	        LocalDate.parse("2026-12-25"),
371	        LocalDate.parse("2026-12-28"));
372	
373	    /**
374	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday, a
375	     * Sunday or a listed public holiday is advanced one day at a time until it lands on a weekday
376	     * that is not a public holiday, while a date already on a non-holiday weekday is returned
377	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
378	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
379	     * falls on a business day.
380	     *
381	     * @param date the effective registration date
382	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
383	     */
384	    private static LocalDate rollToBusinessDay(LocalDate date) {
385	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
386	            date = date.plusDays(1);
387	        }
388	        return date;
389	    }
390	
391	    private static boolean isWeekend(LocalDate date) {
392	        return switch (date.getDayOfWeek()) {
393	            case SATURDAY, SUNDAY -> true;
394	            default -> false;
395	        };
396	    }
397	
398	    /**
399	     * Counts the existing owners whose {@code registrationDate} equals the given (already
400	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
401	     * business day. Called before a new owner is saved, so the returned value reflects the number of
402	     * owners created for that day prior to this create.
403	     *
404	     * @param date the adjusted business-day registration date to count against
405	     * @return the number of existing owners registered on that date
406	     */
407	    private int countOwnersRegisteredOn(LocalDate date) {
408	        return (int) this.clinicService.findAllOwners().stream()
409	            .filter(existing -> date.equals(existing.getRegistrationDate()))
410	            .count();
411	    }
412	
413	    /**
414	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
415	     *
416	     * @param city the city to count owners for
417	     * @return the number of existing owners in that city
418	     */
419	    private int countOwnersInCity(String city) {
420	        return (int) this.clinicService.findAllOwners().stream()
421	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
422	            .count();
423	    }
424	
425	    /**
426	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
427	     * the last two digits of the fiscal year (which starts on 1 July) of the business-day-adjusted
428	     * registration date (e.g. {@code 'NSW-1A2B3C4D-M27'}). The fiscal year is derived via
429	     * {@link OwnerMapper#fiscalYear(LocalDate)}, the single source of truth also used by the DTO's
430	     * {@code fiscalYear} field.
431	     *
432	     * @param customerCode     the owner's assigned customer code
433	     * @param registrationDate the owner's business-day-adjusted registration date
434	     * @return the assigned membership number
435	     */
436	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
437	        String yy = String.format("%02d", OwnerMapper.fiscalYear(registrationDate) % 100);
438	        return String.format("%s-M%s", customerCode, yy);
439	    }
440	
441	    /**
442	     * Counts the existing owners that already share the given first name and last name, comparing
443	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
444	     * the number of namesakes that existed prior to this create.
445	     *
446	     * @param firstName the new owner's first name
447	     * @param lastName  the new owner's last name
448	     * @return the number of existing owners with the same first and last name
449	     */
450	    private int countNamesakes(String firstName, String lastName) {
451	        int count = 0;
452	        for (Owner existing : this.clinicService.findAllOwners()) {
453	            if (firstName.equalsIgnoreCase(existing.getFirstName())
454	                && lastName.equalsIgnoreCase(existing.getLastName())) {
455	                count++;
456	            }
457	        }
458	        return count;
459	    }
460	
461	    /**
462	     * Counts the existing owners that already belong to the given household (i.e. that share the
463	     * given {@code householdId}). Called before a new owner is saved, so adding one for the owner
464	     * being created yields the household's total size at the moment of creation. Owners without a
465	     * household id are ignored.
466	     *
467	     * @param householdId the new owner's assigned household id
468	     * @return the number of existing owners already in that household
469	     */
470	    private int countHouseholdMembers(String householdId) {
471	        if (householdId == null) {
472	            return 0;
473	        }
474	        int count = 0;
475	        for (Owner existing : this.clinicService.findAllOwners()) {
476	            if (householdId.equals(existing.getHouseholdId())) {
477	                count++;
478	            }
479	        }
480	        return count;
481	    }
482	
483	    /**
484	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
485	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
486	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
487	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
488	     * string is what gets stored and returned.
489	     *
490	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
491	     *
492	     * <p>Once in E.164 form the national-number length is validated against the country code: a
493	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
494	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
495	     * rule are accepted on the general 8-to-15 digit length alone.
496	     *
497	     * @param telephone the raw telephone value supplied by the client
498	     * @return the normalized E.164 telephone number
499	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
500	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
501	     *                                 after the {@code '+'}, or the wrong national-number length for
502	     *                                 its country code)
503	     */
504	    private static String normalizeTelephone(String telephone) {
505	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
506	        String digits;
507	        if (cleaned.startsWith("+")) {
508	            digits = cleaned.substring(1);
509	        } else {
510	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
511	            digits = "61" + national;
512	        }
513	        if (!digits.matches("[0-9]{8,15}")) {
514	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
515	                "telephone could not be normalized to a valid E.164 number");
516	        }
517	        validateNationalNumberLength(digits);
518	        return "+" + digits;
519	    }
520	
521	    /**
522	     * Validates the national-number length of an E.164 number (its digits, without the leading
523	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
524	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
525	     * (only the general 8-to-15 digit rule applies).
526	     *
527	     * @param digits the E.164 digits without the leading {@code '+'}
528	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
529	     *                                 digits does not match the country code's required length
530	     */
531	    private static void validateNationalNumberLength(String digits) {
532	        E164PhoneNumbers.countryCode(digits)
533	            .ifPresent(code -> {
534	                int nationalLength = digits.length() - code.length();
535	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
536	                if (nationalLength != required) {
537	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
538	                        "telephone must have " + required
539	                            + " national digits for country code +" + code);
540	                }
541	            });
542	    }
543	
544	    /**
545	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
546	     * containing at least one dot, none of the three sections containing whitespace or an
547	     * additional {@code @}.
548	     */
549	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
550	
551	    /**
552	     * Disposable email domains that are not accepted for an owner. An email whose domain is on this
553	     * blocklist is rejected with {@link HttpStatus#BAD_REQUEST}. Entries are lower-case and matched
554	     * case-insensitively against the domain (the part after the {@code @}).
555	     */
556	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
557	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
558	
559	    /**
560	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
561	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
562	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
563	     * lower-cased.
564	     *
565	     * @param email the raw email value supplied by the client, possibly {@code null}
566	     * @return the lower-cased email, or {@code null} when none was supplied
567	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
568	     *                                 is not a syntactically valid address, or its domain is on the
569	     *                                 disposable-domain blocklist
570	     */
571	    private static String normalizeEmail(String email) {
572	        if (email == null) {
573	            return null;
574	        }
575	        if (!EMAIL_PATTERN.matcher(email).matches()) {
576	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
577	                "email must be a syntactically valid address");
578	        }
579	        String normalized = email.toLowerCase(Locale.ROOT);
580	        String domain = normalized.substring(normalized.indexOf('@') + 1);
581	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
582	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
583	                "email domain " + domain + " is not allowed");
584	        }
585	        return normalized;
586	    }
587	
588	    /**
589	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
590	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
591	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
592	     */
593	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
594	        "NSW", new int[] {2000, 2099},
595	        "VIC", new int[] {3000, 3099},
596	        "QLD", new int[] {4000, 4099});
597	
598	    /**
599	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
600	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
601	     * four-digit format is enforced by request validation; here the value is range-checked: when the
602	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
603	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
604	     * accepts any four-digit postcode.
605	     *
606	     * @param city     the owner's city
607	     * @param postcode the owner's postcode, possibly {@code null}
608	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
609	     *                                 out of range for the city's region
610	     */
611	    private static void validatePostcode(String city, String postcode) {
612	        if (postcode == null) {
613	            return;
614	        }
615	        String region = OwnerMapper.CITY_REGION.get(city);
616	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
617	        if (range == null) {
618	            return;
619	        }
620	        int value = Integer.parseInt(postcode);
621	        if (value < range[0] || value > range[1]) {
622	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
623	                "postcode " + postcode + " is not valid for region " + region);
624	        }
625	    }
626	
627	    /**
628	     * Common street-type abbreviations expanded to their full word during address normalization.
629	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
630	     */
631	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
632	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
633	
634	    /**
635	     * Applies an owner's address, accepting either the structured form (a non-blank
636	     * {@code addressLine1} with an optional {@code addressLine2}) or the flat {@code address} form,
637	     * preferring the structured fields when present. Whichever fields are supplied are normalized
638	     * (see {@link #normalizeAddress(String)}), and the stored flat {@code address} is set to the
639	     * composed value: the normalized {@code addressLine1}, with a single space and the normalized
640	     * {@code addressLine2} appended when an {@code addressLine2} was supplied. When only the flat
641	     * form is supplied, the normalized flat address is stored and both structured lines are cleared.
642	     * This keeps the request contract backward-compatible: an owner that supplied just the flat
643	     * {@code address} (plus city) is still accepted.
644	     *
645	     * @param owner the owner being created or updated, carrying the raw address fields
646	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if neither a non-blank
647	     *                                 {@code addressLine1} nor a non-blank flat {@code address} was
648	     *                                 supplied
649	     */
650	    private static void applyAddress(Owner owner) {
651	        boolean hasStructured = owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank();
652	        boolean hasFlat = owner.getAddress() != null && !owner.getAddress().isBlank();
653	        if (!hasStructured && !hasFlat) {
654	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
655	                "an address must be supplied, either 'addressLine1' or 'address'");
656	        }
657	        if (hasStructured) {
658	            String line1 = normalizeAddress(owner.getAddressLine1());
659	            owner.setAddressLine1(line1);
660	            String composed = line1;
661	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
662	                String line2 = normalizeAddress(owner.getAddressLine2());
663	                owner.setAddressLine2(line2);
664	                composed = line1 + " " + line2;
665	            } else {
666	                owner.setAddressLine2(null);
667	            }
668	            owner.setAddress(composed);
669	        } else {
670	            owner.setAddressLine1(null);
671	            owner.setAddressLine2(null);
672	            owner.setAddress(normalizeAddress(owner.getAddress()));
673	        }
674	    }
675	
676	    /**
677	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
678	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
679	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
680	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
681	     *
682	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
683	     *
684	     * @param address the raw address supplied by the client, possibly {@code null}
685	     * @return the normalized address
686	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
687	     *                                 after normalization (required field)
688	     */
689	    private static String normalizeAddress(String address) {
690	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
691	        if (collapsed.isEmpty()) {
692	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
693	                "address must not be blank");
694	        }
695	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
696	        StringBuilder normalized = new StringBuilder();
697	        for (int i = 0; i < tokens.length; i++) {
698	            if (i > 0) {
699	                normalized.append(' ');
700	            }
701	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
702	        }
703	        return normalized.toString();
704	    }
705	
706	    /**
707	     * Determines whether the given whole identity key already belongs to any owner other than the
708	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
709	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
710	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
711	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
712	     *
713	     * @param identityKey the identity key to look for
714	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
715	     * @return {@code true} if another owner already has the same identity key
716	     */
717	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
718	        for (Owner existing : this.clinicService.findAllOwners()) {
719	            if (existing.isDeleted()) {
720	                continue;
721	            }
722	            if (excludeId != null && excludeId.equals(existing.getId())) {
723	                continue;
724	            }
725	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
726	                return true;
727	            }
728	        }
729	        return false;
730	    }
731	
732	    /**
733	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
734	     * (soft) duplicate of: one that shares the new owner's last name (compared case-insensitively)
735	     * and postcode while carrying a <em>different</em> normalized telephone. A hard duplicate
736	     * (identical identity key) has already been rejected with a 409 before this runs, so this
737	     * flags only the softer last-name/postcode overlap. The match with the lowest id is returned
738	     * so the result is deterministic when several owners qualify.
739	     *
740	     * @param owner the new owner being created, with its telephone already normalized
741	     * @return the matching existing owner, or {@code null} when none qualifies
742	     */
743	    private Owner findPossibleDuplicate(Owner owner) {
744	        if (owner.getLastName() == null || owner.getPostcode() == null) {
745	            return null;
746	        }
747	        return this.clinicService.findAllOwners().stream()
748	            .filter(existing -> !existing.isDeleted())
749	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
750	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
751	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
752	            .min(Comparator.comparingInt(Owner::getId))
753	            .orElse(null);
754	    }
755	
756	}
