55	    /**
56	     * The fiscal year that the given date falls in, where the fiscal year starts on 1 July and is
57	     * identified by the calendar year in which it ends. A date on or after 1 July belongs to the
58	     * fiscal year ending in the following calendar year (e.g. 2026-08-01 -&gt; 2027), while a date
59	     * before 1 July belongs to the fiscal year ending in the same calendar year (e.g. 2026-03-01 -&gt;
60	     * 2026). This is the single source of truth for the fiscal year used by both the DTO's
61	     * {@code fiscalYear} and the create endpoint's membership-number year segment.
62	     *
63	     * @param date the date to resolve, on a business day
64	     * @return the calendar year in which that date's fiscal year ends
65	     */
66	    static int fiscalYear(LocalDate date) {
67	        int year = date.getYear();
68	        return date.getMonthValue() >= Month.JULY.getValue() ? year + 1 : year;
69	    }
70	
71	    /**
72	     * Derive an owner's fiscal year from its business-day-adjusted {@code registrationDate},
73	     * formatted {@code 'FY<YY>'} where YY is the last two digits of the fiscal year (see
74	     * {@link #fiscalYear(LocalDate)}), e.g. {@code 'FY27'}. Returns {@code null} when no registration
75	     * date is present (the field is then absent from the DTO).
76	     */
77	    default String toFiscalYear(Owner owner) {
78	        LocalDate registrationDate = owner.getRegistrationDate();
79	        return registrationDate == null ? null : String.format("FY%02d", fiscalYear(registrationDate) % 100);
80	    }
81	
82	    /**
83	     * Derive an owner's salutation: the {@code title}, a single space, and the {@code lastName}
84	     * (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the salutation is
85	     * just the last name.
86	     */
87	    default String toSalutation(Owner owner) {
88	        String lastName = owner.getLastName();
89	        String title = owner.getTitle();
90	        if (title == null || title.isBlank()) {
91	            return lastName;
92	        }
93	        return title + " " + lastName;
94	    }
95	
96	    /**
97	     * Derive an owner's age band from the {@code birthDate} relative to the {@code registrationDate}:
98	     * 'MINOR' when under 18, 'ADULT' when 18 to 64, and 'SENIOR' when 65 or older. Returns
99	     * {@code null} when no birth date was supplied (the band is then absent from the DTO). When the
100	     * registration date is missing (e.g. legacy records) the current date is used as the reference.
101	     */
102	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
103	        LocalDate birthDate = owner.getBirthDate();
104	        if (birthDate == null) {
105	            return null;
106	        }
107	        LocalDate reference = owner.getRegistrationDate() != null
108	            ? owner.getRegistrationDate() : LocalDate.now();
109	        int age = Period.between(birthDate, reference).getYears();
110	        if (age < 18) {
111	            return OwnerDto.AgeBandEnum.MINOR;
112	        }
113	        if (age < 65) {
114	            return OwnerDto.AgeBandEnum.ADULT;
115	        }
116	        return OwnerDto.AgeBandEnum.SENIOR;
117	    }
118	
119	    /**
120	     * Format an owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
121	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
122	     * The raw {@code telephone} property is left untouched in E.164 form. Returns the value unchanged
123	     * when it is {@code null} or not in {@code '+'}-prefixed E.164 form.
124	     *
125	     * <p>The recognized dialling codes come from {@link E164PhoneNumbers}, the same table the create
126	     * endpoint validates against, so the two paths cannot diverge. When a number carries no recognized
127	     * code, a two-digit country code is assumed (the most common length).
128	     */
129	    default String toTelephoneDisplay(Owner owner) {
130	        String telephone = owner.getTelephone();
131	        if (telephone == null || !telephone.startsWith("+")) {
132	            return telephone;
133	        }
134	        String digits = telephone.substring(1);
135	        String code = E164PhoneNumbers.countryCode(digits)
136	            .filter(c -> digits.length() > c.length())
137	            .orElse(digits.length() > 2 ? digits.substring(0, 2) : digits);
138	        String national = digits.substring(code.length());
139	        StringBuilder sb = new StringBuilder("+").append(code);
140	        for (int i = 0; i < national.length(); i += 3) {
141	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
142	        }
143	        return sb.toString();
144	    }
145	
146	    /**
147	     * Derive an owner's check digit: a single Luhn check digit (0-9) computed over the digits
148	     * contained in the {@code customerCode}. Non-digit characters (the separators) are ignored.
149	     */
150	    default Integer toCheckDigit(Owner owner) {
151	        String code = owner.getCustomerCode();
152	        if (code == null) {
153	            return null;
154	        }
155	        int sum = 0;
156	        boolean dbl = true;
157	        for (int i = code.length() - 1; i >= 0; i--) {
158	            char c = code.charAt(i);
159	            if (c < '0' || c > '9') {
160	                continue;
161	            }
162	            int d = c - '0';
163	            if (dbl) {
164	                d *= 2;
165	                if (d > 9) {
166	                    d -= 9;
167	                }
168	            }
169	            sum += d;
170	            dbl = !dbl;
171	        }
172	        return (10 - (sum % 10)) % 10;
173	    }
174	
175	    /**
176	     * Derive an owner's duplicate-detection identity key: the normalized E.164 telephone, the
177	     * lower-cased email (empty when none), and the household id (empty when none), joined with
178	     * {@code '|'}. Two owners are duplicates only when their whole identity keys are equal.
179	     *
180	     * <p>This is the single source of truth for the key: it is both returned on the DTO and used by
181	     * the create endpoint's 409 duplicate check, so the value clients see is exactly the value that
182	     * governs rejection. The "email present" rule reuses {@link #hasEmail(Owner)}.
183	     */
184	    default String toIdentityKey(Owner owner) {
185	        String email = hasEmail(owner) ? owner.getEmail() : "";
186	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
187	        return owner.getTelephone() + "|" + email + "|" + household;
188	    }
189	
190	    /**
191	     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
192	     * for the "is an email present" rule shared by the derived fields below.
193	     */
194	    default boolean hasEmail(Owner owner) {
195	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
196	    }
197	
198	    /**
199	     * Derive an owner's preferred contact channel: 'EMAIL' when an email address is present,
200	     * otherwise 'PHONE'.
201	     */
202	    default String toContactPreference(Owner owner) {
203	        return hasEmail(owner) ? "EMAIL" : "PHONE";
204	    }
205	
206	    /**
207	     * Derive an owner's membership points: start at 0; add 2 when an email address is present; add 1
208	     * when the owner has no namesakes (namesakeCount is 0); add 2 when the owner belongs to a
209	     * household of 3 or more (see {@link #hasHouseholdBonus(Owner)}); add 3 when the owner's tenure
210	     * is at least one elapsed fiscal year (see {@link #hasTenureBonus(Owner)}). Because a newly
211	     * created owner has zero tenure it never earns the tenure points, so a new owner with an email
212	     * and no namesakes in a single-member household scores 3 points.
213	     */
214	    default Integer toMembershipPoints(Owner owner) {
215	        int points = 0;
216	        if (hasEmail(owner)) {
217	            points += 2;
218	        }
219	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
220	        if (noNamesakes) {
221	            points += 1;
222	        }
223	        if (hasHouseholdBonus(owner)) {
224	            points += 2;
225	        }
226	        if (hasTenureBonus(owner)) {
227	            points += 3;
228	        }
229	        return points;
230	    }
231	
232	    /**
233	     * Whether the owner belongs to a household of 3 or more members. The household size is the count
234	     * of owners sharing the owner's household id, frozen at creation (see the create endpoint).
235	     * Returns {@code false} when no household size is present (e.g. legacy records).
236	     */
237	    default boolean hasHouseholdBonus(Owner owner) {
238	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
239	    }
240	
241	    /**
242	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
243	     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
244	     * or more.
245	     */
246	    default Integer toMembershipLevel(Owner owner) {
247	        int points = toMembershipPoints(owner);
248	        if (points <= 1) {
249	            return 1;
250	        }
251	        if (points <= 3) {
252	            return 2;
253	        }
254	        if (points <= 5) {
255	            return 3;
256	        }
257	        return 4;
258	    }
259	
260	    /**
261	     * Whether the owner's tenure is at least one elapsed fiscal year, i.e. the fiscal year of the
262	     * current date is later than the fiscal year of the {@code registrationDate} (fiscal years start
263	     * on 1 July; see {@link #fiscalYear(LocalDate)}). A brand-new owner (registered in the current
264	     * fiscal year) has zero elapsed fiscal years and so never qualifies. Returns {@code false} when
265	     * no registration date is present.
266	     */
267	    default boolean hasTenureBonus(Owner owner) {
268	        LocalDate registrationDate = owner.getRegistrationDate();
269	        if (registrationDate == null) {
270	            return false;
271	        }
272	        return fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) >= 1;
273	    }
274	
275	    /**
276	     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
277	     */
278	    Map<String, String> CITY_REGION = Map.of(
279	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
280	
281	    /**
282	     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
283	     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
284	     * inclusive.
285	     */
286	    Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
287	        "NSW", new int[] {2000, 2099},
288	        "VIC", new int[] {3000, 3099},
289	        "QLD", new int[] {4000, 4099});
290	
291	    /**
292	     * Derive an owner's locality (region) from the region-and-hash customer code: the {@code <REGION>}
293	     * segment of the {@code customerCode}, i.e. everything before the first {@code '-'}. Since the
294	     * region is baked into the customer code at creation (see the create endpoint), the locality now
295	     * moves with that identity rather than being recomputed from the postcode and city. When an owner
296	     * has no customer code yet (e.g. legacy records), fall back to deriving the region directly via
297	     * {@link #regionOf(Owner)}.
298	     */
299	    default String toLocality(Owner owner) {
300	        String code = owner.getCustomerCode();
301	        if (code != null) {
302	            int dash = code.indexOf('-');
303	            if (dash > 0) {
304	                return code.substring(0, dash);
305	            }
306	        }
307	        return regionOf(owner);
308	    }
309	
310	    /**
311	     * Fixed region-to-IANA-timezone table used to derive an owner's timezone: NSW -> Australia/Sydney,
312	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane.
313	     */
314	    Map<String, String> REGION_TIMEZONE = Map.of(
315	        "NSW", "Australia/Sydney",
316	        "VIC", "Australia/Melbourne",
317	        "QLD", "Australia/Brisbane");
318	
319	    /**
320	     * Derive an owner's IANA timezone name from its locality/region (see {@link #toLocality(Owner)})
321	     * via the fixed {@link #REGION_TIMEZONE} table. Returns {@code null} when the region resolves to no
322	     * entry in the table (e.g. 'UNKNOWN'), so the timezone is then absent from the DTO.
323	     */
324	    default String toTimezone(Owner owner) {
325	        return REGION_TIMEZONE.get(toLocality(owner));
326	    }
327	
328	    /**
329	     * Derive an owner's region, preferring the postcode: when the postcode is present and falls within
330	     * a known region's range (see {@link #REGION_POSTCODE_RANGES}) that region wins. When the postcode
331	     * is absent or in no known range, fall back to the fixed {@link #CITY_REGION} table. Returns
332	     * 'UNKNOWN' when neither the postcode nor the city resolves a region. This is the region baked into
333	     * the {@code <REGION>} segment of a new owner's customer code and, through it, the owner's locality.
334	     */
335	    default String regionOf(Owner owner) {
336	        // Prefer the postcode: the region whose range contains it wins. The logic is kept here (rather
337	        // than in a String -> String helper) because MapStruct would treat such a helper as an implicit
338	        // type conversion and wrongly apply it to other String properties (e.g. telephone).
339	        String postcode = owner.getPostcode();
340	        if (postcode != null) {
341	            try {
342	                int value = Integer.parseInt(postcode.trim());
343	                for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
344	                    int[] range = entry.getValue();
345	                    if (value >= range[0] && value <= range[1]) {
346	                        return entry.getKey();
347	                    }
348	                }
349	            }
350	            catch (NumberFormatException ignored) {
351	                // Non-numeric postcode: fall back to the city table below.
352	            }
353	        }
354	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
355	    }
356	
357	    Owner toOwner(OwnerDto ownerDto);
358	
359	    @Mapping(target = "id", ignore = true)
360	    @Mapping(target = "pets", ignore = true)
361	    Owner toOwner(OwnerFieldsDto ownerDto);
362	
363	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
364	
365	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
366	
367	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
368	        OwnerPageDto ownerPageDto = new OwnerPageDto();
369	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
370	        ownerPageDto.setPage(ownerPage.getNumber());
371	        ownerPageDto.setSize(ownerPage.getSize());
372	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
373	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
374	        return ownerPageDto;
375	    }
376	}
